function voiceJobCompletionBrowserJs() {
  return String.raw`;(()=>{const nativeFetch=window.fetch.bind(window);window.fetch=async(input,init)=>{const response=await nativeFetch(input,init);try{const url=typeof input==='string'?input:input instanceof URL?input.pathname:input.url;const method=String(init?.method||(typeof input==='object'&&'method'in input?input.method:'GET')).toUpperCase();if(method==='POST'&&new URL(url,location.href).pathname==='/api/streamweaver/control/voice'&&response.ok){const value=await response.clone().json();if(value?.jobId)window.dispatchEvent(new CustomEvent('spmt:streamweaver-voice-job',{detail:{jobId:value.jobId,kind:value.kind,destination:value.destination}}))}}catch{}return response};const status=(message,state='')=>document.querySelectorAll('[data-sw-status]').forEach(node=>{node.textContent=message;node.dataset.state=state});window.addEventListener('spmt:streamweaver-voice-job',event=>{const detail=event.detail||{};if(detail.kind==='suite-action')setTimeout(()=>status('Action queued. Waiting for its owning app to finish it.','ready'),0);void(async()=>{for(let attempt=0;attempt<80;attempt+=1){await new Promise(done=>setTimeout(done,750));try{const response=await nativeFetch('/api/streamweaver/control/voice/jobs/'+encodeURIComponent(detail.jobId),{credentials:'same-origin',cache:'no-store'}),job=await response.json();if(!response.ok)throw new Error(job.message||job.error||'Voice job could not be read');if(job.state==='succeeded'){const text=job.result?.text||job.result?.output?.text;if(text){status(text,'ready')}else{const provider=job.result?.provider||detail.destination||'provider';status('Delivered to '+provider+'.','ready')}return}if(['failed','dead-letter','cancelled'].includes(job.state)){status(job.error?.message||job.lastError||'Voice request did not complete.','error');return}status(detail.kind==='assistant'?'Your persona is thinking…':detail.kind==='suite-action'?'Waiting for the owning app to finish the action…':'Waiting for connected channel delivery…')}catch(error){if(attempt===79)status(error instanceof Error?error.message:String(error),'error')}}status('Voice request is still running. Check activity for its final result.','error')})()})})();`;
}

function suiteActionStatusBrowserJs() {
  return String.raw`;(()=>{let runtime=null,botActions=[];const write=(node,value)=>{if(node&&node.textContent!==value)node.textContent=value};function decorate(){if(!runtime)return;const slot=document.querySelector('[data-spmt-live-slot="commands"]');if(!slot)return;const heading=[...slot.querySelectorAll('h3')].find(node=>node.textContent==='Role-gated bot actions');if(heading){const copy=heading.nextElementSibling;write(copy,runtime.suiteActionsMessage);const card=heading.closest('.sw-card');if(card){let badge=card.querySelector('[data-sw-suite-state]');if(!badge){badge=document.createElement('span');badge.className='sw-badge';badge.dataset.swSuiteState='';card.insertBefore(badge,heading)}write(badge,'Suite adapters · '+String(runtime.suiteActions||'setup-required').replace('-',' '))}}const actions=slot.querySelector('.sw-actions');if(actions&&!actions.querySelector('[data-sw-chat-state]')){const badge=document.createElement('span');badge.className='sw-badge';badge.dataset.swChatState='';write(badge,runtime.publicCommands==='connected'?'Chat runtime · connected':'Chat runtime · setup required');actions.append(badge)}const readiness=new Map(botActions.map(action=>[action.id,action.availability]));for(const code of slot.querySelectorAll('.sw-command code')){const id=code.textContent||'';if(!/^(?:dsh\.|hmo\.|sw\.)/.test(id))continue;const card=code.closest('.sw-command');if(card){let state=card.querySelector('[data-sw-action-state]');if(!state){state=document.createElement('small');state.dataset.swActionState='';card.append(state)}write(state,readiness.get(id)==='connected'?'Ready through the shared SPMT action pipeline':'Owning app worker setup required')}}}new MutationObserver(decorate).observe(document.body,{childList:true,subtree:true});fetch('/api/streamweaver/control',{credentials:'same-origin',cache:'no-store'}).then(response=>response.json()).then(value=>{runtime=value.botRuntime;botActions=value.botActions||[];decorate()}).catch(()=>{})})();`;
}

function controlBrowserJs() {
  const commands = JSON.stringify(COMMAND_UI).replace(/</g, "\\u003c");
  return String.raw`;(()=>{const appId='streamweaver',commands=__COMMANDS__;let state=null,history=[],recording=false,recognition=null;const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const slot=id=>document.querySelector('[data-spmt-live-slot="'+CSS.escape(id)+'"]');function shellAccount(){window.parent.postMessage({protocol:'spmt.surface',version:1,type:'shell.navigate',appId,view:'account'},'*')}function setStatus(message,kind=''){for(const node of document.querySelectorAll('[data-sw-status]')){node.textContent=message;node.dataset.state=kind}}function connectionOptions(provider,selected=''){const rows=(state?.connections||[]).filter(item=>item.provider===provider);return'<option value="">'+(rows.length?'Choose connected channel':'No connected '+provider+' channel')+'</option>'+rows.map(item=>'<option value="'+escapeHtml(item.connectionId)+'"'+(item.connectionId===selected?' selected':'')+'>'+escapeHtml(item.connectionId+' · '+item.channelId)+'</option>').join('')}function renderVoice(){const node=slot('voice');if(!node)return;node.innerHTML='<div class="sw-shell"><article class="sw-card"><div class="sw-commander"><div class="sw-actions"><button type="button" class="button primary sw-mic" data-sw-mic data-recording="false" aria-label="Start voice recording">🎙</button></div><form class="sw-form" data-sw-voice><span class="sw-badge">Explicit microphone · press V</span><label>What you want to say<textarea name="message" maxlength="5000" required placeholder="Press the microphone and speak, or type here…"></textarea></label><div class="sw-form two"><label>Destination<select name="destination"><option value="ai">AI Bot · remembered conversation</option><option value="private">Private · do not remember</option><option value="twitch">Twitch chat</option><option value="discord">Discord channel</option></select></label><label data-sw-connection-wrap hidden>Connected channel<select name="connectionId"></select></label></div><div class="sw-actions"><button class="button primary">Send</button><button type="button" class="button" data-sw-clear>Clear history</button></div></form></div></article><article class="sw-card"><span class="sw-badge">Recent Voice Commander actions</span><div class="sw-history" data-sw-history>'+(history.length?history.map(item=>'<article><strong>'+escapeHtml(item.destination)+'</strong><p>'+escapeHtml(item.message)+'</p><small>'+escapeHtml(item.status)+'</small></article>').join(''):'<p class="sw-muted">Nothing sent in this browser session.</p>')+'</div></article><div class="sw-status" data-sw-status aria-live="polite"></div></div>';const form=node.querySelector('[data-sw-voice]'),dest=form.elements.destination,conn=form.elements.connectionId,wrap=node.querySelector('[data-sw-connection-wrap]');function syncDestination(){const provider=dest.value;if(provider==='twitch'||provider==='discord'){wrap.hidden=false;conn.innerHTML=connectionOptions(provider);conn.required=true}else{wrap.hidden=true;conn.required=false;conn.innerHTML=''}}dest.addEventListener('change',syncDestination);syncDestination();form.addEventListener('submit',event=>{event.preventDefault();void sendVoice(form)});node.querySelector('[data-sw-mic]').addEventListener('click',toggleMic);node.querySelector('[data-sw-clear]').addEventListener('click',()=>{history=[];renderVoice()})}function toggleMic(){const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SpeechRecognition){setStatus('This browser does not provide speech recognition. Type the command in the box instead.','error');return}if(recognition&&recording){recognition.stop();return}const input=slot('voice')?.querySelector('textarea[name="message"]');recognition=new SpeechRecognition();recognition.continuous=false;recognition.interimResults=true;recognition.lang=navigator.language||'en-US';recognition.onstart=()=>{recording=true;const button=slot('voice')?.querySelector('[data-sw-mic]');if(button){button.dataset.recording='true';button.textContent='■'}setStatus('Listening… press again to stop.')};recognition.onresult=event=>{let text='';for(let i=event.resultIndex;i<event.results.length;i++)text+=event.results[i][0].transcript;if(input)input.value=text.trim()};recognition.onerror=event=>setStatus('Microphone or speech recognition failed: '+event.error,'error');recognition.onend=()=>{recording=false;const button=slot('voice')?.querySelector('[data-sw-mic]');if(button){button.dataset.recording='false';button.textContent='🎙'}setStatus(input?.value?'Transcript ready. Review it, then send.':'Listening stopped.')};recognition.start()}async function sendVoice(form){const button=form.querySelector('button[type="submit"],button:not([type])');if(button)button.disabled=true;setStatus('Routing Voice Commander request…');try{const data=Object.fromEntries(new FormData(form).entries());data.idempotencyKey='voice:'+Date.now()+':'+Math.random().toString(36).slice(2);const response=await fetch('/api/streamweaver/control/voice',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify(data)}),value=await response.json();if(!response.ok)throw new Error(value.message||value.reason||value.error||'Voice request failed');history.unshift({destination:data.destination,message:data.message,status:value.status==='accepted'?'Assistant job accepted':'Delivery queued'});history=history.slice(0,8);renderVoice();setStatus(value.status==='accepted'?'Your persona is thinking. The accepted job is visible in activity.':'Queued for the connected provider.','ready')}catch(error){setStatus(error instanceof Error?error.message:String(error),'error')}finally{if(button)button.disabled=false}}function renderCommands(){const node=slot('commands');if(!node)return;const families=[...new Set(commands.map(item=>item.family))].sort();node.innerHTML='<div class="sw-shell"><div class="sw-toolbar"><input class="sw-search" data-sw-command-search placeholder="Search commands, aliases, or families"><select class="sw-search" data-sw-command-family><option value="">All command groups</option>'+families.map(f=>'<option>'+escapeHtml(f)+'</option>').join('')+'</select></div><section><div class="sw-actions"><span class="sw-badge">'+commands.length+' public commands</span><span class="sw-badge">'+(state.botActions?.length||0)+' suite actions</span></div><div class="sw-catalog" data-sw-command-list></div></section><section class="sw-card"><h3>Role-gated bot actions</h3><p>These cross-app actions are detected from explicit chat language. The chat sender’s provider role is checked before any write or broadcast action runs.</p><div class="sw-catalog">'+(state.botActions||[]).map(action=>'<article class="sw-command"><code>'+escapeHtml(action.id)+'</code><small>'+escapeHtml(action.risk+' · '+action.minimumRole+' or higher')+'</small></article>').join('')+'</div></section></div>';const search=node.querySelector('[data-sw-command-search]'),family=node.querySelector('[data-sw-command-family]'),list=node.querySelector('[data-sw-command-list]');function draw(){const q=search.value.trim().toLowerCase(),f=family.value;const rows=commands.filter(item=>(!f||item.family===f)&&(!q||JSON.stringify(item).toLowerCase().includes(q))).slice(0,120);list.innerHTML=rows.map(item=>'<article class="sw-command"><code>'+escapeHtml(item.trigger)+'</code><strong>'+escapeHtml(item.family)+'</strong><small>'+(item.aliases.length?'Aliases: '+escapeHtml(item.aliases.join(', ')):'No aliases')+(item.cooldownSeconds?' · '+item.cooldownSeconds+'s cooldown':'')+'</small></article>').join('')||'<p class="sw-muted">No commands match that search.</p>'}search.addEventListener('input',draw);family.addEventListener('change',draw);draw()}function personaValues(){return state.personaDocument?.values||{}}function renderPersona(){const node=slot('persona');if(!node)return;const p=personaValues(),owner=state.role==='owner';node.innerHTML='<div class="sw-shell"><article class="sw-card"><span class="sw-badge">How routing works</span><h3>'+escapeHtml(state.persona?.displayName||p.displayName||'Assistant')+'</h3><p>The owner can summon this persona casually. Other chatters must mention it, and outside home channels the owner opens a temporary summon window.</p></article>'+(owner?'<form class="sw-card sw-form two" data-sw-post="persona"><label>Persona ID<input name="personaId" value="'+escapeHtml(p.personaId||'persona-default')+'" required></label><label>Display name<input name="displayName" value="'+escapeHtml(p.displayName||'Assistant')+'" required></label><label>Aliases<textarea name="aliases" required>'+escapeHtml(p.aliases||'assistant')+'</textarea></label><label>Home channel IDs<textarea name="homeChannelIds">'+escapeHtml(p.homeChannelIds||'')+'</textarea></label><label>External summon window (minutes)<input type="number" min="1" max="120" name="summonWindowMinutes" value="'+escapeHtml(p.summonWindowMinutes||10)+'" required></label><label>Memory<select name="memoryPolicy"><option value="conversation"'+(p.memoryPolicy!=='off'?' selected':'')+'>Remember this persona conversation</option><option value="off"'+(p.memoryPolicy==='off'?' selected':'')+'>Do not remember</option></select></label><label class="sw-span">Persona instructions<textarea name="instructions" maxlength="4000" required>'+escapeHtml(p.instructions||'Be accurate, helpful, concise, and faithful to the configured presentation.')+'</textarea></label><button class="button primary sw-span">Save persona</button></form>':'<div class="sw-card"><p>Only the tenant owner can change bot and persona settings.</p></div>')+'<div class="sw-status" data-sw-status aria-live="polite"></div></div>';bindForms(node)}function renderIntegrations(){const node=slot('integrations');if(!node)return;const links=state.providerLinks||[],connections=state.connections||[];node.innerHTML='<div class="sw-shell"><article class="sw-card"><span class="sw-badge">Personal identity</span><h3>Linked accounts</h3><p>Twitch and Discord identities belong to your SPMT Account. StreamWeaver only receives the scoped access it needs.</p><div class="sw-grid">'+(links.length?links.map(item=>'<article class="sw-card sw-connection"><span class="sw-provider">'+escapeHtml(String(item.provider||'?').slice(0,1).toUpperCase())+'</span><div><strong>'+escapeHtml(item.provider)+'</strong><p>'+escapeHtml(item.displayName||item.username||item.providerUserId)+'</p></div></article>').join(''):'<div class="sw-card"><p>No personal provider identity is linked.</p></div>')+'</div><div class="sw-actions"><button type="button" class="button primary" data-sw-account>Manage linked accounts</button></div></article><article class="sw-card"><span class="sw-badge">Bot runtime</span><h3>Connected chat channels</h3><p>These are the channel connections the provider-neutral Chat Gateway can actually send to.</p><div class="sw-grid">'+(connections.length?connections.map(item=>'<article class="sw-card sw-connection"><span class="sw-provider">'+escapeHtml(item.provider.slice(0,1).toUpperCase())+'</span><div><strong>'+escapeHtml(item.provider+' · '+item.connectionId)+'</strong><p>Channel '+escapeHtml(item.channelId)+'</p></div></article>').join(''):'<div class="sw-card"><p>No Twitch, Discord, or Kick bot channel is configured for this tenant.</p></div>')+'</div></article><div class="sw-status" data-sw-status></div></div>';node.querySelector('[data-sw-account]').addEventListener('click',shellAccount)}function renderEconomy(){const node=slot('economy');if(!node)return;const e=state.economy||{},s=e.settings||{},owner=state.role==='owner';node.innerHTML='<div class="sw-shell"><div class="sw-grid"><article class="sw-card"><span class="sw-badge">Your wallet</span><strong class="sw-wallet">'+escapeHtml(e.wallet?.balance||0)+' '+escapeHtml(s.currencyName||'Credits')+'</strong><p>'+escapeHtml(e.wallet?.totalEarned||0)+' lifetime earned. This is not SPMT XP.</p></article><article class="sw-card"><span class="sw-badge">Leaderboard</span>'+(e.leaderboard?.length?e.leaderboard.map(item=>'<p>#'+escapeHtml(item.rank)+' · '+escapeHtml(item.userId)+' · '+escapeHtml(item.balance)+'</p>').join(''):'<p>No local currency activity yet.</p>')+'</article></div>'+(owner?'<form class="sw-card sw-form two" data-sw-post="economy"><label>Currency name<input name="currencyName" value="'+escapeHtml(s.currencyName||'Credits')+'" required></label><label>Default bet<input type="number" min="1" name="defaultBet" value="'+escapeHtml(s.defaultBet||1234)+'" required></label><label>Minimum bet<input type="number" min="0" name="minBet" value="'+escapeHtml(s.minBet||0)+'" required></label><label>Maximum bet (0 = wallet limit)<input type="number" min="0" name="maxBet" value="'+escapeHtml(s.maxBet||0)+'" required></label><label>Win chance %<input type="number" min="0" max="100" name="winPercent" value="'+escapeHtml(s.winPercent||28)+'" required></label><label>Jackpot chance %<input type="number" min="0" max="100" name="jackpotPercent" value="'+escapeHtml(s.jackpotPercent||1)+'" required></label><label>Jackpot multiplier<input type="number" min="1" name="jackpotMultiplier" value="'+escapeHtml(s.jackpotMultiplier||1)+'" required></label><label class="sw-check"><input type="checkbox" name="spmtExchangeEnabled" '+(s.spmtExchangeEnabled?'checked':'')+'> Allow bounded SPMT exchange</label><label>Local per SPMT<input type="number" min="1" name="baseLocalPerSpmt" value="'+escapeHtml(s.baseLocalPerSpmt||1000)+'" required></label><label>Reference supply<input type="number" min="1" name="referenceSupply" value="'+escapeHtml(s.referenceSupply||1000000)+'" required></label><label>Maximum SPMT per exchange<input type="number" min="1" name="maxSpmtPerExchange" value="'+escapeHtml(s.maxSpmtPerExchange||100)+'" required></label><button class="button primary sw-span">Save economy</button></form>':'<div class="sw-card"><p>Only the tenant owner can change creator-currency rules.</p></div>')+'<div class="sw-status" data-sw-status aria-live="polite"></div></div>';bindForms(node)}function bindForms(root){root.querySelectorAll('[data-sw-post]').forEach(form=>form.addEventListener('submit',event=>{event.preventDefault();void submit(form)}))}async function submit(form){const button=form.querySelector('button[type="submit"],button:not([type])');if(button)button.disabled=true;setStatus('Saving…');try{const data=Object.fromEntries(new FormData(form).entries());for(const input of form.querySelectorAll('input[type="number"]'))data[input.name]=Number(input.value);for(const checkbox of form.querySelectorAll('input[type="checkbox"]'))data[checkbox.name]=checkbox.checked;const response=await fetch('/api/streamweaver/control/'+form.dataset.swPost,{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify(data)}),value=await response.json();if(!response.ok)throw new Error(value.message||value.error||'Save failed');setStatus('Saved.','ready');await load()}catch(error){setStatus(error instanceof Error?error.message:String(error),'error')}finally{if(button)button.disabled=false}}async function load(){for(const id of ['voice','commands','persona','integrations','economy']){const node=slot(id);if(node)node.innerHTML='<small>Loading StreamWeaver controls…</small>'}try{const response=await fetch('/api/streamweaver/control',{credentials:'same-origin',cache:'no-store'}),value=await response.json();if(!response.ok)throw new Error(value.message||value.error||'Controls unavailable');state=value;renderVoice();renderCommands();renderPersona();renderIntegrations();renderEconomy()}catch(error){const message=escapeHtml(error instanceof Error?error.message:String(error));for(const id of ['voice','commands','persona','integrations','economy']){const node=slot(id);if(node)node.innerHTML='<div class="sw-card"><p>'+message+'</p></div>'}}}window.addEventListener('keydown',event=>{if(event.key.toLowerCase()==='v'&&!event.ctrlKey&&!event.altKey&&!event.metaKey&&!event.repeat&&!['INPUT','TEXTAREA','SELECT'].includes(event.target?.tagName)){event.preventDefault();toggleMic()}});window.addEventListener('spmt:snapshot',()=>void load());setTimeout(()=>void load(),0)})();`.replace("__COMMANDS__", commands);
}

function flowBrowserJs() {
  return String.raw`;(()=>{let flows=null,control=null,platform=null,query='',busy=false;const slot=id=>document.querySelector('[data-spmt-live-slot="'+CSS.escape(id)+'"]'),escapeHtml=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char])),installedIds=()=>new Set((flows?.installed||[]).map(item=>item.packageId)),commandOf=item=>item?.commands?.[0]||null;function navigate(id){document.querySelector('[data-nav="'+CSS.escape(id)+'"]')?.click()}function status(message,state=''){for(const node of document.querySelectorAll('[data-sw-flow-status]')){node.textContent=message;node.dataset.state=state}}function downloadUrl(item,format='streamweaver'){const suffix=format==='streamerbot'?'/export/streamerbot':'/export';return'/api/streamweaver/control/flows/'+encodeURIComponent(item.packageId)+suffix}async function post(path,body){const response=await fetch('/api/streamweaver/control/flows/'+path,{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify(body)}),value=await response.json();if(!response.ok)throw new Error(value.message||value.reason||value.error||'Flow request failed');return value}function flowCard(item,mode){const command=commandOf(item),installed=installedIds().has(item.packageId),allEnabled=[...(item.commands||[]),...(item.actions||[])].every(step=>step.enabled!==false),buttons=[];if(mode==='community')buttons.push('<button type="button" class="button '+(installed?'':'primary')+'" data-sw-flow-action="'+(installed?'uninstall':'install')+'" data-package-id="'+escapeHtml(item.packageId)+'">'+(installed?'Remove':'Install this flow')+'</button>');if(mode==='draft'&&!allEnabled)buttons.push('<button type="button" class="button primary" data-sw-flow-action="approve" data-package-id="'+escapeHtml(item.packageId)+'">Approve & install</button>');else if(mode==='draft'&&!installed)buttons.push('<button type="button" class="button primary" data-sw-flow-action="install" data-package-id="'+escapeHtml(item.packageId)+'">Install this flow</button>');else if(mode==='draft'&&installed)buttons.push('<button type="button" class="button" data-sw-flow-action="uninstall" data-package-id="'+escapeHtml(item.packageId)+'">Remove</button>');if(mode==='draft'&&item.visibility==='private')buttons.push('<button type="button" class="button" data-sw-flow-action="publish" data-package-id="'+escapeHtml(item.packageId)+'">Share with community</button>');buttons.push('<a class="button" href="'+downloadUrl(item)+'" download>Download this JSON</a>','<a class="button" href="'+downloadUrl(item,'streamerbot')+'" download>Streamer.bot JSON</a>');return'<article class="sw-flow-card" data-package="'+escapeHtml(item.packageId)+'"><div class="sw-flow-meta"><span>one flow</span><span>'+escapeHtml(item.packageKind)+'</span>'+(installed?'<span>installed</span>':'')+'</div><h3 class="sw-flow-code">'+escapeHtml(command?.trigger||item.name)+'</h3><p>'+escapeHtml(item.description||'Portable StreamWeaver flow.')+'</p><small>By '+escapeHtml(item.author?.displayName||item.author?.id||'community')+' · '+escapeHtml((item.actions||[]).length)+' action step'+((item.actions||[]).length===1?'':'s')+'</small><div class="sw-actions">'+buttons.join('')+'</div></article>'}function renderSetup(){const node=slot('setup');if(!node||!flows||!control)return;const count=flows.installed.length,links=control.providerLinks?.length||0,connections=control.connections?.length||0,persona=Boolean(control.persona),outputs=platform?.tenantOutputs;const step=(complete,title,body,button,action)=>'<article class="sw-flow-step" data-complete="'+complete+'"><i>'+(complete?'✓':'○')+'</i><div><strong>'+escapeHtml(title)+'</strong><small>'+escapeHtml(body)+'</small></div><button type="button" class="button" data-sw-flow-action="'+action+'">'+escapeHtml(button)+'</button></article>';node.innerHTML='<div class="sw-shell"><section class="sw-flow-lead"><span class="sw-badge">Blank means blank</span><span class="sw-flow-count">'+count+'</span><h3>installed command flow'+(count===1?'':'s')+'</h3><p>Your account was not preloaded with disabled commands. The original library remains outside your account until you choose an individual JSON.</p></section><section class="sw-flow-steps">'+step(count>0,'1. Choose starting commands',count?count+' individual flow'+(count===1?' is':'s are')+' installed.':'Zero is valid. Browse the '+flows.community.length+' optional originals and install only what you want.','Browse library','nav-community')+step(links>0,'2. Connect your accounts',links?links+' personal provider account'+(links===1?' is':'s are')+' linked.':'Link Twitch or Discord identity through your SPMT Account.','Open integrations','nav-integrations')+step(connections>0,'3. Set up bot functions',connections?connections+' bot channel'+(connections===1?' is':'s are')+' connected.':'Choose which connected channels may receive StreamWeaver bot traffic.','Bot setup','nav-integrations')+step(persona,'4. Configure your bot persona',persona?'Your tenant persona is configured.':'Choose its name, aliases, instructions, home channels, and memory boundary.','Bot & Persona','nav-persona')+step(false,'5. Learn Voice Commander','Press the microphone, speak or type, choose a private AI or connected channel destination, review, then send.','Voice tutorial','nav-voice')+step(Boolean(outputs?.public?.sceneId||outputs?.personal?.sceneId),'6. Build ecosystem overlays','Overlay Bay—not StreamWeaver—owns Public OBS and signed-in Personal workspace compositions.','Overlay Bay','overlay-bay')+step(false,'7. Ask AI for one custom flow','Describe one command or automation. Review its one-flow JSON, approve it, use it, and share it if you choose.','Build one flow','nav-builder')+'</section><article class="sw-card"><h3>Public and Personal overlay URLs</h3><p>Add the Public URL to OBS as one browser source. For console streaming, capture Remote Play/gameplay, compose it with ecosystem widgets in Overlay Bay, then send that composited feed through your RTMP/restream workflow. Personal can be different and follows you across signed-in app workspaces; the shared footer turns it on or off.</p><div class="sw-actions"><button type="button" class="button" data-sw-flow-action="copy-public">Copy Public URL</button><button type="button" class="button" data-sw-flow-action="copy-personal">Copy Personal URL</button></div></article><div class="sw-flow-status" data-sw-flow-status aria-live="polite"></div></div>'}function renderCommunity(){const node=slot('community');if(!node||!flows)return;const rows=flows.community.filter(item=>!query||JSON.stringify(item).toLowerCase().includes(query)).slice(0,200);node.innerHTML='<div class="sw-shell"><section class="sw-flow-lead"><span class="sw-badge">Community library · not installed</span><span class="sw-flow-count">'+flows.community.length+'</span><h3>independent JSON flow packages</h3><p>Every card is its own import/export unit. Choosing one never pulls in the rest of an author’s library.</p></section><div class="sw-toolbar"><input class="sw-search" data-sw-flow-search value="'+escapeHtml(query)+'" placeholder="Search command, author, tag, or collection"><span class="sw-badge">'+flows.installed.length+' installed</span></div><section class="sw-flow-library">'+(rows.map(item=>flowCard(item,'community')).join('')||'<div class="sw-flow-empty">No community flows match that search.</div>')+'</section><div class="sw-flow-status" data-sw-flow-status aria-live="polite"></div></div>';node.querySelector('[data-sw-flow-search]')?.addEventListener('input',event=>{query=event.target.value.trim().toLowerCase();renderCommunity()})}function renderBuilder(){const node=slot('builder');if(!node||!flows)return;node.innerHTML='<div class="sw-shell"><section class="sw-flow-lead"><span class="sw-badge">Zero computer skills required</span><h3>Tell StreamWeaver what one flow should do</h3><p>The shared SPMT assistant can use StreamWeaver steps and registered cross-app capabilities. It returns one private JSON for review; it does not install a command library.</p></section><form class="sw-card sw-form" data-sw-ai-flow><label>Describe one command or automation<textarea name="idea" maxlength="4000" required placeholder="When someone types !welcome, greet them by name and show my welcome widget…"></textarea></label><button class="button primary">Build one flow with AI</button></form><form class="sw-card sw-form" data-sw-import-flow><label>Or import one StreamWeaver flow JSON<textarea name="json" required placeholder="Paste one streamweaver.flow-package JSON object"></textarea></label><button class="button primary">Import this one flow</button></form><section><h3>Your private drafts</h3><div class="sw-flow-library">'+(flows.drafts.map(item=>flowCard(item,'draft')).join('')||'<div class="sw-flow-empty">No private drafts yet. Describe one flow above or import one JSON.</div>')+'</div></section><div class="sw-flow-status" data-sw-flow-status aria-live="polite"></div></div>';node.querySelector('[data-sw-import-flow]')?.addEventListener('submit',event=>{event.preventDefault();void(async()=>{try{status('Importing one flow…');const raw=new FormData(event.currentTarget).get('json'),value=JSON.parse(String(raw));await post('import',{package:value});status('That one flow is installed.','ready');await load()}catch(error){status(error instanceof Error?error.message:String(error),'error')}})()});node.querySelector('[data-sw-ai-flow]')?.addEventListener('submit',event=>{event.preventDefault();void(async()=>{try{status('Asking the shared assistant to build one flow…');const idea=String(new FormData(event.currentTarget).get('idea')||''),result=await post('ai',{idea,idempotencyKey:'flow-ai:'+Date.now()+':'+Math.random().toString(36).slice(2)});if(result.status==='blocked'){status(result.reason||'AI creation is blocked in read-only mode.','error');return}status('The AI is building one reviewable JSON…');for(let attempt=0;attempt<80;attempt+=1){await new Promise(done=>setTimeout(done,750));const completed=await post('ai/complete',{jobId:result.jobId});if(completed.state==='succeeded'){status('One private flow draft is ready for review.','ready');await load();return}}throw new Error('The flow is still building. Its job remains available in activity.')}catch(error){status(error instanceof Error?error.message:String(error),'error')}})()})}function renderInstalled(){const node=slot('commands');if(!node)return;if(!flows){node.innerHTML='<small>Loading installed flows…</small>';return}const packages=[...flows.community,...flows.drafts].filter(item=>installedIds().has(item.packageId)),suite=control?.botActions||[];node.innerHTML='<div class="sw-shell" data-sw-installed-flow-view><section class="sw-flow-lead"><span class="sw-badge">This account only</span><span class="sw-flow-count">'+packages.length+'</span><h3>installed flow'+(packages.length===1?'':'s')+'</h3><p>Only these flows can handle chat for this tenant. The other community packages are not present here.</p></section>'+(packages.length?'<section class="sw-flow-library">'+packages.map(item=>flowCard(item,item.visibility==='private'?'draft':'community')).join('')+'</section>':'<section class="sw-flow-empty"><strong>No commands or flows are installed.</strong><span>Your account is genuinely blank. Browse the community library or ask AI to build one.</span><div class="sw-actions"><button type="button" class="button primary" data-sw-flow-action="nav-community">Browse individual flows</button><button type="button" class="button" data-sw-flow-action="nav-builder">Build one with AI</button></div></section>')+'<section class="sw-card"><h3>Registered cross-app actions</h3><p>Installed flows may call these typed SPMT capabilities. Provider roles are checked before write or broadcast actions run.</p><div class="sw-catalog">'+suite.map(action=>'<article class="sw-command"><code>'+escapeHtml(action.id)+'</code><small>'+escapeHtml(action.risk+' · '+action.minimumRole+' or higher · '+action.availability)+'</small></article>').join('')+'</div></section><div class="sw-flow-status" data-sw-flow-status aria-live="polite"></div></div>'}function renderAll(){renderSetup();renderCommunity();renderBuilder();renderInstalled()}async function load(){if(busy)return;busy=true;try{const [flowResponse,controlResponse]=await Promise.all([fetch('/api/streamweaver/control/flows',{credentials:'same-origin',cache:'no-store'}),fetch('/api/streamweaver/control',{credentials:'same-origin',cache:'no-store'})]),flowValue=await flowResponse.json(),controlValue=await controlResponse.json();if(!flowResponse.ok)throw new Error(flowValue.message||flowValue.error||'Flow library unavailable');if(!controlResponse.ok)throw new Error(controlValue.message||controlValue.error||'StreamWeaver controls unavailable');flows=flowValue;control=controlValue;renderAll();if(!flows.installed.length&&!sessionStorage.getItem('streamweaver:setup-seen')){sessionStorage.setItem('streamweaver:setup-seen','1');navigate('setup')}}catch(error){const message=escapeHtml(error instanceof Error?error.message:String(error));for(const id of ['setup','community','builder','commands']){const node=slot(id);if(node)node.innerHTML='<div class="sw-flow-empty">'+message+'</div>'}}finally{busy=false}}window.__streamweaverFlowBrowserRenderCommands=renderInstalled;document.addEventListener('click',event=>{const button=event.target.closest?.('[data-sw-flow-action]');if(!button)return;const action=button.dataset.swFlowAction,id=button.dataset.packageId||'';if(action?.startsWith('nav-')){navigate(action.slice(4));return}if(action==='overlay-bay'){document.querySelector('[data-spmt-open-overlay-bay]')?.click();return}if(action==='copy-public'||action==='copy-personal'){document.querySelector(action==='copy-public'?'[data-spmt-copy-public]':'[data-spmt-copy-personal]')?.click();status((action==='copy-public'?'Public':'Personal')+' URL copied.','ready');return}if(!['install','uninstall','approve','publish'].includes(action)||!id)return;void(async()=>{try{button.disabled=true;status(action==='uninstall'?'Removing that one flow…':action==='publish'?'Publishing that one flow…':'Adding that one flow…');await post(action,{packageId:id});status(action==='uninstall'?'That flow was removed.':action==='publish'?'That flow is now in the community library.':'That one flow is installed.','ready');await load()}catch(error){status(error instanceof Error?error.message:String(error),'error')}finally{button.disabled=false}})()});window.addEventListener('spmt:snapshot',event=>{platform=event.detail||platform;renderSetup()});const commandsSlot=slot('commands');if(commandsSlot)new MutationObserver(()=>{if(flows&&!commandsSlot.querySelector('[data-sw-installed-flow-view]'))renderInstalled()}).observe(commandsSlot,{childList:true});setTimeout(()=>void load(),0)})();`;
}

function simulationRoomBrowserJs() {
  return String.raw`;(()=>{let packages=new Map(),loading=false;const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));function status(message,state=''){document.querySelectorAll('[data-sw-flow-status]').forEach(node=>{node.textContent=message;node.dataset.state=state})}async function load(){if(loading)return;loading=true;try{const response=await fetch('/api/streamweaver/control/flows',{credentials:'same-origin',cache:'no-store'}),value=await response.json();if(!response.ok)return;packages=new Map([...(value.community||[]),...(value.drafts||[])].map(item=>[item.packageId,item]));decorate()}catch{}finally{loading=false}}function decorate(){for(const card of document.querySelectorAll('.sw-flow-card[data-package]')){if(card.dataset.simulationReady==='true')continue;const item=packages.get(card.dataset.package);if(!item)continue;const actions=card.querySelector('.sw-actions');if(!actions)continue;for(const command of item.commands||[]){const button=document.createElement('button');button.type='button';button.className='button';button.dataset.swSimPreview='';button.dataset.packageId=item.packageId;button.dataset.commandId=command.id;button.textContent='Preview '+command.trigger+(command.role==='addon'?' add-on':'');actions.prepend(button)}card.dataset.simulationReady='true'}}function render(result){const node=document.querySelector('[data-spmt-live-slot="shadow-rooms"]');if(!node)return;const outputs=result.outputs||[];node.innerHTML='<div class="sw-shell"><section class="sw-flow-lead"><span class="sw-badge">Tenant simulation · no provider egress</span><h3>'+escapeHtml(result.command?.trigger||'Flow preview')+'</h3><p>Room '+escapeHtml(result.roomId)+' received the exact synthetic input and app output below. Other tenants cannot read this room.</p></section><article class="sw-card"><span class="sw-badge">chat · ingress</span><strong>'+escapeHtml(result.input)+'</strong></article>'+(outputs.length?outputs.map(output=>'<article class="sw-card"><span class="sw-badge">'+escapeHtml(output.type)+'</span><strong>'+escapeHtml(output.text)+'</strong><small>'+escapeHtml(output.actionId)+'</small></article>').join(''):'<article class="sw-card"><span class="sw-badge">app · preview</span><strong>This command completed without a visible output.</strong></article>')+'</div>'}document.addEventListener('click',event=>{const button=event.target.closest?.('[data-sw-sim-preview]');if(!button)return;void(async()=>{try{button.disabled=true;status('Running this command in your tenant simulation room…');const response=await fetch('/api/streamweaver/control/flows/preview',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({packageId:button.dataset.packageId,commandId:button.dataset.commandId})}),value=await response.json();if(!response.ok)throw new Error(value.message||value.error||'Preview failed');status('Preview stayed inside your tenant simulation room.','ready');document.querySelector('[data-nav="shadow-rooms"]')?.click();setTimeout(()=>render(value),0)}catch(error){status(error instanceof Error?error.message:String(error),'error')}finally{button.disabled=false}})()});new MutationObserver(()=>{decorate();if(!packages.size)void load()}).observe(document.body,{childList:true,subtree:true});setTimeout(()=>void load(),0)})();`;
}

function simulationRoomLauncherBrowserJs() {
  return String.raw`;(()=>{const nativeFetch=window.fetch.bind(window);window.fetch=async(input,init)=>{const response=await nativeFetch(input,init);try{const path=new URL(typeof input==='string'?input:input instanceof URL?input:input.url,location.href).pathname,method=String(init?.method||'GET').toUpperCase();if(method==='POST'&&path==='/api/streamweaver/control/flows/preview'&&response.ok)setTimeout(()=>document.querySelector('[data-spmt-open-simulation-rooms]')?.click(),0)}catch{}return response}})();`;
}

function operationModeBrowserJs() {
  return String.raw`;(()=>{let readOnly=false;const nativeFetch=window.fetch.bind(window),write=(node,value)=>{if(node&&node.textContent!==value)node.textContent=value};window.fetch=async(input,init)=>{const response=await nativeFetch(input,init);try{const path=new URL(typeof input==='string'?input:input instanceof URL?input:input.url,location.href).pathname,method=String(init?.method||'GET').toUpperCase();if(method==='GET'&&path==='/api/streamweaver/control'&&response.ok){const value=await response.clone().json();readOnly=value?.operationMode==='read-only';if(readOnly)setTimeout(decorate,0)}if(method==='POST'&&path==='/api/streamweaver/control/voice'&&response.ok){const value=await response.clone().json();if(value?.status==='blocked')setTimeout(()=>{document.querySelectorAll('[data-sw-status]').forEach(node=>{write(node,value.reason||'Blocked by read-only mode.');node.dataset.state='ready'});decorate()},0)}}catch{}return response};function decorate(){if(!readOnly)return;const form=document.querySelector('[data-sw-voice]');if(!form)return;if(!form.querySelector('[data-sw-read-only]')){const badge=document.createElement('span');badge.className='sw-badge read-only';badge.dataset.swReadOnly='';write(badge,'Live input · provider replies go to shadow rooms');form.prepend(badge)}const button=form.querySelector('button[type="submit"],button:not([type])');write(button,'Run safely in shadow mode')}new MutationObserver(decorate).observe(document.body,{childList:true,subtree:true});})();`;
}

if (process.env.SPMT_ORIGIN) {
  const host = createStreamWeaverWebServer({ spmtOrigin: process.env.SPMT_ORIGIN, port: Number(process.env.PORT ?? 3202), host: process.env.HOST ?? "127.0.0.1", buildSha: process.env.BUILD_SHA ?? "dev", operationMode: process.env.SPMT_OUTBOUND_MODE === "disabled" ? "read-only" : "active", ...(process.env.STREAMWEAVER_DATABASE_PATH ? { databasePath: process.env.STREAMWEAVER_DATABASE_PATH } : {}), ...(process.env.STREAMWEAVER_WORKER_CREDENTIAL ? { credential: process.env.STREAMWEAVER_WORKER_CREDENTIAL } : {}), ...(process.env.CHAT_GATEWAY_CONNECTIONS ? { connectionsJson: process.env.CHAT_GATEWAY_CONNECTIONS } : {}) });
  await host.listen();
}
